   299→
   300→    const jsonCandidate = this.extractJsonObject(content);
   301→    if (!jsonCandidate) return false;
   302→
   303→    try {
   304→      const parsed = JSON.parse(jsonCandidate);
   305→      if (!parsed || typeof parsed !== 'object') return false;
   306→
   307→      // Chart configuration: has chart_type/graphType + data keys
   308→      if (
   309→        ('chart_type' in parsed || 'graphType' in parsed) &&
   310→        ('labels' in parsed || 'datasets' in parsed || 'data' in parsed)
   311→      ) {
   312→        return true;
   313→      }
   314→
   315→      // Chart reference map: all keys match "chart-XXXX" pattern with string values
   316→      const keys = Object.keys(parsed);
   317→      if (
   318→        keys.length > 0 &&
   319→        keys.every((k) => /^chart-/.test(k) && typeof parsed[k] === 'string')
   320→      ) {
   321→        return true;
   322→      }
   323→
   324→      return false;
   325→    } catch {
   326→      return false;
   327→    }
   328→  }
   329→
   330→  /**
   331→   * Extract a JSON object string from content that may have surrounding text.
   332→   * Returns the JSON substring if found, or null.
   333→   */
   334→  private extractJsonObject(content: string): string | null {
   335→    let trimmed = content.trim();
   336→
   337→    // Pure JSON case (most common)
   338→    if (trimmed.startsWith('{') && trimmed.endsWith('}')) {
   339→      return trimmed;
   340→    }
   341→
   342→    // Strip markdown code fences: ```json ... ``` or ``` ... ```
   343→    const fenceMatch = trimmed.match(/```(?:json)?\s*(\{[\s\S]*\})\s*```/);
   344→    if (fenceMatch) {
   345→      return fenceMatch[1].trim();
   346→    }
   347→
   348→    // Find the outermost { ... } in the content
   349→    const firstBrace = trimmed.indexOf('{');
   350→    const lastBrace = trimmed.lastIndexOf('}');
   351→    if (firstBrace !== -1 && lastBrace > firstBrace) {
   352→      return trimmed.substring(firstBrace, lastBrace + 1);
   353→    }
   354→
   355→    return null;
   356→  }
   357→}
