    result: any;
    newMessages: Message[];
}
declare abstract class AbstractAgent {
    agentId?: string;
    description: string;
    threadId: string;
    messages: Message[];
    state: State;
    debug: boolean;
    subscribers: AgentSubscriber[];
    isRunning: boolean;
    private middlewares;
