    43→      // library-generated threadId (uuid v4) from the original instance.
    44→      const threadId = this.agent.threadId;
    45→      this.agent = new HttpAgent({
    46→        url: `${environment.apiUrl}${environment.agentEndpoint}`,
    47→        threadId,
    48→        initialMessages: this.chatState
    49→          .messages()
    50→          .filter((msg) => msg.role === 'user')
    51→          .slice(-environment.maxMessageHistory)
    52→          .map((msg, index) => ({
    53→            id: msg.id || `msg-${index}`,
    54→            role: 'user' as const,
    55→            content: [{ type: 'text' as const, text: msg.content }],
    56→          })),
    57→        initialState: this.sharedState.agentContext(),
    58→      });
