   136→  private handleEvent(event: BaseEvent): void {
   137→    console.log('AG-UI Event:', event.type, event);
   138→
   139→    switch (event.type) {
   140→      case 'RUN_STARTED':
   141→        this.chatState.isStreaming.set(true);
   142→        break;
   143→
   144→      case 'TEXT_MESSAGE_START':
   145→        this.chatState.startAssistantMessage();
   146→        break;
   147→
   148→      case 'TEXT_MESSAGE_CONTENT':
   149→        // Events use 'delta' property, not 'content'
   150→        if ('delta' in event && typeof event['delta'] === 'string') {
   151→          this.chatState.appendStreamingContent(event['delta']);
   152→        }
   153→        break;
   154→
   155→      case 'TEXT_MESSAGE_END':
   156→        // Check if the completed message is raw chart JSON (not meant for display).
   157→        // We must read the accumulated content from the messages array, NOT from
   158→        // currentStreamingMessage(), because appendStreamingContent() creates new
   159→        // objects in the messages array while currentStreamingMessage still holds
   160→        // the original object with content: ''.
   161→        const streamingMsg = this.chatState.currentStreamingMessage();
   162→        if (streamingMsg) {
   163→          const actualMessage = this.chatState
   164→            .messages()
   165→            .find((m) => m.id === streamingMsg.id);
   166→          if (
   167→            actualMessage &&
   168→            this.isChartJsonContent(actualMessage.content)
   169→          ) {
   170→            // Remove this message - it's chart config, not a user-facing response
   171→            this.chatState.removeMessage(streamingMsg.id);
   172→            this.chatState.currentStreamingMessage.set(null);
   173→            this.chatState.isStreaming.set(false);
   174→          } else {
