   181→
   182→      case 'TOOL_CALL_START':
   183→        // Events use 'toolCallName' property, not 'toolName'
   184→        if ('toolCallName' in event) {
   185→          this.chatState.addToolCall({
   186→            toolName: String(event['toolCallName']),
   187→            status: 'running',
   188→          });
   189→        }
   190→        break;
   191→
   192→      case 'TOOL_CALL_ARGS':
   193→        // Events use 'toolCallName' property, not 'toolName'
   194→        if ('toolCallName' in event && 'args' in event) {
   195→          this.chatState.addToolCall({
   196→            toolName: String(event['toolCallName']),
   197→            status: 'running',
   198→            arguments: event['args'] as Record<string, any>,
   199→          });
   200→        }
   201→        break;
   202→
   203→      case 'TOOL_CALL_END':
   204→        // Events use 'toolCallName' property, not 'toolName'
   205→        if ('toolCallName' in event) {
   206→          this.chatState.addToolCall({
   207→            toolName: String(event['toolCallName']),
   208→            status: 'complete',
   209→            executionTimeMs: 'executionTimeMs' in event ? Number(event['executionTimeMs']) : undefined,
   210→          });
   211→        }
   212→        break;
   213→
   214→      case 'TOOL_CALL_RESULT':
   215→        // Handle tool call results - check for A2UI payload in content
   216→        if ('content' in event && event['content']) {
   217→          const content = event['content'];
   218→
   219→          // Content is typically a JSON string, so parse it first
   220→          try {
   221→            const parsed = typeof content === 'string' ? JSON.parse(content) : content;
   222→
   223→            // Check if this is an A2UI visualization payload
   224→            // Backend returns: {a2ui: true, surfaceId: "...", messages: [{beginRendering: ...}, {surfaceUpdate: ...}, ...]}
   225→            if (parsed && parsed.a2ui === true && parsed.surfaceId && parsed.messages && Array.isArray(parsed.messages)) {
   226→              console.log('A2UI visualization detected:', parsed.surfaceId);
   227→              console.log('A2UI messages from backend:', parsed.messages);
