   248→        if ('state' in event && event['state']) {
   249→          // For now, just log it - we could update the full context if needed
   250→          console.log('State snapshot received:', event['state']);
   251→        }
   252→        break;
   253→
   254→      case 'CUSTOM':
   255→        if ('name' in event && event['name'] === 'a2ui_surface_update' && 'data' in event) {
   256→          const data = event['data'] as any;
   257→          // Check if this is the new message format
   258→          if (data && data.surfaceId && data.messages && Array.isArray(data.messages)) {
   259→            this.a2uiEventService.handleA2UIMessages(data.surfaceId, data.messages);
   260→          }
   261→        }
   262→        break;
   263→
   264→      case 'RUN_FINISHED':
   265→        this.chatState.isStreaming.set(false);
   266→        break;
   267→
   268→      case 'RUN_ERROR':
