   291→  /**
   292→   * Detect if message content is raw chart JSON config (not user-facing text).
   293→   * Handles both pure JSON and content where JSON is wrapped with minor
   294→   * surrounding text or markdown fences.
   295→   */
   296→  private isChartJsonContent(content: string): boolean {
   297→    if (!content || !content.trim()) return false;
   298→
   299→    const jsonCandidate = this.extractJsonObject(content);
   300→    if (!jsonCandidate) return false;
   301→
   302→    try {
   303→      const parsed = JSON.parse(jsonCandidate);
   304→      if (!parsed || typeof parsed !== 'object') return false;
   305→
   306→      // Chart configuration: has chart_type/graphType + data keys
   307→      if (
   308→        ('chart_type' in parsed || 'graphType' in parsed) &&
   309→        ('labels' in parsed || 'datasets' in parsed || 'data' in parsed)
   310→      ) {
   311→        return true;
   312→      }
   313→
   314→      // Chart reference map: all keys match "chart-XXXX" pattern with string values
   315→      const keys = Object.keys(parsed);
   316→      if (
   317→        keys.length > 0 &&
   318→        keys.every((k) => /^chart-/.test(k) && typeof parsed[k] === 'string')
   319→      ) {
   320→        return true;
   321→      }
   322→
   323→      return false;
   324→    } catch {
   325→      return false;
   326→    }
   327→  }
   328→
   329→  /**
   330→   * Extract a JSON object string from content that may have surrounding text.
   331→   * Returns the JSON substring if found, or null.
   332→   */
   333→  private extractJsonObject(content: string): string | null {
   334→    let trimmed = content.trim();
   335→
   336→    // Pure JSON case (most common)
   337→    if (trimmed.startsWith('{') && trimmed.endsWith('}')) {
   338→      return trimmed;
   339→    }
   340→
   341→    // Strip markdown code fences: ```json ... ``` or ``` ... ```
   342→    const fenceMatch = trimmed.match(/```(?:json)?\s*(\{[\s\S]*\})\s*```/);
   343→    if (fenceMatch) {
   344→      return fenceMatch[1].trim();
   345→    }
   346→
   347→    // Find the outermost { ... } in the content
   348→    const firstBrace = trimmed.indexOf('{');
   349→    const lastBrace = trimmed.lastIndexOf('}');
   350→    if (firstBrace !== -1 && lastBrace > firstBrace) {
   351→      return trimmed.substring(firstBrace, lastBrace + 1);
   352→    }
   353→
   354→    return null;
   355→  }
   356→}
