     5→/**
     6→ * ChatStateService
     7→ *
     8→ * Manages conversation messages, streaming status, and session identity.
     9→ * All state is managed through Angular signals for reactive updates.
    10→ */
    11→@Injectable({
    12→  providedIn: 'root',
    13→})
    14→export class ChatStateService {
    15→  // Core signals
    16→  readonly messages = signal<ChatMessage[]>([]);
    17→  readonly isStreaming = signal<boolean>(false);
    18→  readonly currentStreamingMessage = signal<ChatMessage | null>(null);
    19→  readonly error = signal<string | null>(null);
    20→
    21→  // Computed signals
    22→  readonly lastVisualization = computed(() => {
    23→    const msgs = this.messages();
    24→    // Find the most recent message with an A2UI payload
    25→    for (let i = msgs.length - 1; i >= 0; i--) {
    26→      if (msgs[i].a2uiPayload !== null) {
    27→        return msgs[i];
    28→      }
    29→    }
    30→    return null;
    31→  });
    32→
    33→  readonly messageCount = computed(() => this.messages().length);
    34→
    35→  readonly hasActiveConversation = computed(() => this.messageCount() > 0);
    36→
    37→  /**
    38→   * Add a user message to the conversation
    39→   */
    40→  addUserMessage(content: string): void {
    41→    const message: ChatMessage = {
    42→      id: this.generateMessageId(),
    43→      role: 'user',
    44→      content: content.trim(),
    45→      timestamp: new Date(),
    46→      isStreaming: false,
    47→      a2uiPayload: null,
    48→      toolCalls: null,
    49→    };
    50→
    51→    this.messages.update((msgs) => [...msgs, message]);
    52→    this.clearError();
    53→  }
    54→
    55→  /**
    56→   * Start a new assistant message (called when TEXT_MESSAGE_START event received).
    57→   * Guards against creating a duplicate message when one is already streaming.
    58→   */
    59→  startAssistantMessage(): void {
    60→    // If there's already an active streaming message, finalize it first
    61→    if (this.currentStreamingMessage()) {
    62→      this.finalizeStreamingMessage();
    63→    }
    64→
    65→    const message: ChatMessage = {
    66→      id: this.generateMessageId(),
    67→      role: 'assistant',
    68→      content: '',
    69→      timestamp: new Date(),
    70→      isStreaming: true,
    71→      a2uiPayload: null,
    72→      toolCalls: null,
    73→    };
    74→
    75→    this.messages.update((msgs) => [...msgs, message]);
    76→    this.currentStreamingMessage.set(message);
    77→    this.isStreaming.set(true);
