    98→  finalizeStreamingMessage(): void {
    99→    const current = this.currentStreamingMessage();
   100→    if (!current) return;
   101→
   102→    // Look up the actual accumulated content (current ref may be stale)
   103→    const actualMsg = this.messages().find((m) => m.id === current.id);
   104→    const finalContent = actualMsg?.content?.trim() || '';
   105→
   106→    // Check for duplicate: does a *previous* finalized assistant message
   107→    // already have the same content?
   108→    if (finalContent) {
   109→      const isDuplicate = this.messages().some(
   110→        (m) =>
   111→          m.id !== current.id &&
   112→          m.role === 'assistant' &&
   113→          !m.isStreaming &&
   114→          m.content.trim() === finalContent
   115→      );
