   123→        this.isStreaming.set(false);
   124→        return;
   125→      }
   126→    }
   127→
   128→    // Remove empty assistant messages (no content and no tool calls / a2ui payload)
   129→    if (!finalContent && !actualMsg?.toolCalls?.length && !actualMsg?.a2uiPayload) {
   130→      this.messages.update((msgs) =>
   131→        msgs.filter((m) => m.id !== current.id)
   132→      );
   133→      this.currentStreamingMessage.set(null);
   134→      this.isStreaming.set(false);
   135→      return;
   136→    }
   137→
   138→    this.messages.update((msgs) =>
   139→      msgs.map((msg) =>
   140→        msg.id === current.id ? { ...msg, isStreaming: false } : msg
   141→      )
   142→    );
   143→
   144→    this.currentStreamingMessage.set(null);
   145→    this.isStreaming.set(false);
   146→  }
   147→
   148→  /**
   149→   * Add a tool call to the current streaming message
   150→   */
   151→  addToolCall(toolInfo: ToolCallInfo): void {
   152→    const current = this.currentStreamingMessage();
   153→    if (!current) return;
   154→
   155→    this.messages.update((msgs) =>
   156→      msgs.map((msg) => {
   157→        if (msg.id === current.id) {
   158→          const existingCalls = msg.toolCalls || [];
   159→          // Check if this tool call already exists (by name) and update it
   160→          const existingIndex = existingCalls.findIndex(
   161→            (call) => call.toolName === toolInfo.toolName
   162→          );
   163→
   164→          const updatedCalls =
   165→            existingIndex >= 0
   166→              ? existingCalls.map((call, idx) =>
   167→                  idx === existingIndex ? toolInfo : call
   168→                )
   169→              : [...existingCalls, toolInfo];
   170→
   171→          return { ...msg, toolCalls: updatedCalls };
   172→        }
   173→        return msg;
   174→      })
   175→    );
   176→  }
   177→
   178→  /**
   179→   * Attach an A2UI payload to the current streaming message
   180→   */
   181→  attachA2UIPayload(payload: A2UISurface): void {
   182→    const current = this.currentStreamingMessage();
   183→    if (!current) {
   184→      // If no streaming message, attach to the last assistant message
   185→      this.messages.update((msgs) => {
   186→        const lastAssistant = [...msgs]
   187→          .reverse()
   188→          .find((m) => m.role === 'assistant');
   189→        if (!lastAssistant) return msgs;
   190→
   191→        return msgs.map((msg) =>
   192→          msg.id === lastAssistant.id ? { ...msg, a2uiPayload: payload } : msg
   193→        );
   194→      });
   195→      return;
   196→    }
   197→
   198→    this.messages.update((msgs) =>
   199→      msgs.map((msg) =>
   200→        msg.id === current.id ? { ...msg, a2uiPayload: payload } : msg
   201→      )
   202→    );
   203→  }
   204→
   205→  /**
   206→   * Remove a message by ID (e.g., chart JSON messages not meant for display)
   207→   */
   208→  removeMessage(messageId: string): void {
   209→    this.messages.update((msgs) => msgs.filter((m) => m.id !== messageId));
   210→  }
   211→
   212→  /**
   213→   * Set an error message
   214→   */
   215→  setError(message: string): void {
   216→    this.error.set(message);
   217→    this.isStreaming.set(false);
   218→    this.currentStreamingMessage.set(null);
   219→  }
   220→
   221→  /**
   222→   * Clear the current error
   223→   */
   224→  clearError(): void {
   225→    this.error.set(null);
   226→  }
   227→
   228→  /**
   229→   * Clear all messages (reset conversation)
   230→   */
   231→  clearMessages(): void {
   232→    this.messages.set([]);
   233→    this.currentStreamingMessage.set(null);
   234→    this.isStreaming.set(false);
   235→    this.clearError();
   236→  }
   237→
   238→  /**
   239→   * Generate a unique message ID
   240→   */
   241→  private generateMessageId(): string {
   242→    return `msg_${Date.now()}_${Math.random().toString(36).substring(2, 9)}`;
   243→  }
   244→}
