   261→          }
   262→          filterContext = {
   263→            drillDownLabel: action.label,
   264→            drillDownValue: action.value,
   265→            drillDownDataset: action.datasetLabel,
   266→          };
   267→        } else if (action.row) {
   268→          // Table row drill-down
   269→          const firstValue = Object.values(action.row)[0];
   270→          message = `Show details for ${firstValue}`;
   271→          filterContext = {
   272→            drillDownRow: action.row,
   273→          };
   274→        }
   275→        break;
   276→
   277→      case 'detail_request':
